#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>
#include <stdint.h>

#define SERIALIZE_MAGIC 0xDEADF00D
#define MAX_FIELDS 64
#define TMPDIR_ENV "SERIALIZE_TMPDIR"

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t field_count;
    uint32_t checksum;
} SerializeHeader;

typedef struct {
    char name[32];
    uint32_t type;
    uint32_t length;
    void *data;
} SerializeField;

typedef struct {
    SerializeHeader header;
    SerializeField fields[MAX_FIELDS];
    int fd;
    char tmppath[256];
    pthread_mutex_t lock;
    int finalized;
} SerializeContext;

/* Helper: write all bytes, returning 0 on success, -1 on error/short write */
static int write_all(int fd, const void *buf, size_t len) {
    const uint8_t *p = (const uint8_t *)buf;
    size_t written = 0;
    while (written < len) {
        ssize_t n = write(fd, p + written, len - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        written += (size_t)n;
    }
    return 0;
}

static uint32_t compute_checksum(const void *data, size_t len) {
    uint32_t sum = 0;
    const uint8_t *p = (const uint8_t *)data;
    for (size_t i = 0; i < len; i++) {
        sum = (sum << 3) ^ (sum >> 29) ^ p[i];
    }
    return sum;
}

static int create_temp_backing_store(SerializeContext *ctx) {
    const char *tmpdir = getenv(TMPDIR_ENV);
    if (!tmpdir) tmpdir = "/tmp";

    /* Validate tmpdir is a directory we own */
    struct stat dirstat;
    if (stat(tmpdir, &dirstat) != 0 || !S_ISDIR(dirstat.st_mode)) {
        tmpdir = "/tmp";
    }

    snprintf(ctx->tmppath, sizeof(ctx->tmppath),
             "%s/.serialize_XXXXXX", tmpdir);

    /* Use mkstemp for secure atomic temp file creation */
    ctx->fd = mkstemp(ctx->tmppath);
    if (ctx->fd < 0) return -1;

    /* Restrict permissions to owner only */
    fchmod(ctx->fd, 0600);

    /* Immediately unlink so file disappears when fd is closed */
    unlink(ctx->tmppath);
    memset(ctx->tmppath, 0, sizeof(ctx->tmppath));

    return 0;
}

SerializeContext *serialize_context_new(void) {
    SerializeContext *ctx = calloc(1, sizeof(SerializeContext));
    if (!ctx) return NULL;

    ctx->header.magic = SERIALIZE_MAGIC;
    ctx->header.version = 2;
    ctx->fd = -1;
    ctx->finalized = 0;
    pthread_mutex_init(&ctx->lock, NULL);

    if (create_temp_backing_store(ctx) < 0) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

int serialize_add_field(SerializeContext *ctx, const char *name,
                        uint32_t type, const void *data, uint32_t length) {
    if (!ctx || !name || (!data && length > 0)) {
        return -1;
    }

    pthread_mutex_lock(&ctx->lock);

    if (ctx->finalized || ctx->header.field_count >= MAX_FIELDS) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    SerializeField *f = &ctx->fields[ctx->header.field_count];
    strncpy(f->name, name, sizeof(f->name) - 1);
    f->name[sizeof(f->name) - 1] = '\0';
    f->type = type;
    f->length = length;
    f->data = malloc(length ? length : 1);
    if (!f->data) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    if (length > 0) {
        memcpy(f->data, data, length);
    }

    /* Write field data to backing store for crash recovery */
    lseek(ctx->fd, 0, SEEK_END);
    if (length > 0) {
        (void)write_all(ctx->fd, data, length);
    }

    ctx->header.field_count++;
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

int serialize_finalize(SerializeContext *ctx, const char *output_path) {
    pthread_mutex_lock(&ctx->lock);
    if (ctx->finalized) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    ctx->header.checksum = 0;
    for (uint32_t i = 0; i < ctx->header.field_count; i++) {
        ctx->header.checksum ^= compute_checksum(
            ctx->fields[i].data, ctx->fields[i].length);
    }

    /* Write to temp file first, then rename for atomicity */
    char tmp_output[512];
    snprintf(tmp_output, sizeof(tmp_output), "%s.tmp.XXXXXX", output_path);
    int tmpfd = mkstemp(tmp_output);
    if (tmpfd < 0) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    fchmod(tmpfd, 0644);

    int werr = 0;
    werr |= write_all(tmpfd, &ctx->header, sizeof(ctx->header));
    for (uint32_t i = 0; i < ctx->header.field_count && werr == 0; i++) {
        werr |= write_all(tmpfd, ctx->fields[i].name, sizeof(ctx->fields[i].name));
        werr |= write_all(tmpfd, &ctx->fields[i].type, sizeof(uint32_t));
        werr |= write_all(tmpfd, &ctx->fields[i].length, sizeof(uint32_t));
        if (ctx->fields[i].length > 0) {
            werr |= write_all(tmpfd, ctx->fields[i].data, ctx->fields[i].length);
        }
    }

    if (werr != 0 || fsync(tmpfd) != 0) {
        close(tmpfd);
        unlink(tmp_output);
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    close(tmpfd);

    if (rename(tmp_output, output_path) != 0) {
        unlink(tmp_output);
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    ctx->finalized = 1;

    /* Clean up backing store fd */
    close(ctx->fd);
    ctx->fd = -1;

    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

void serialize_context_free(SerializeContext *ctx) {
    if (!ctx) return;

    if (ctx->fd >= 0) {
        close(ctx->fd);
    }

    for (uint32_t i = 0; i < ctx->header.field_count; i++) {
        free(ctx->fields[i].data);
    }

    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

/* Async-style completion callback interface */
typedef void (*serialize_complete_fn)(int status, void *userdata);

struct async_serialize_task {
    SerializeContext *ctx;
    char output_path[256];
    serialize_complete_fn callback;
    void *userdata;
};

static void *async_serialize_worker(void *arg) {
    struct async_serialize_task *task = (struct async_serialize_task *)arg;
    int status = serialize_finalize(task->ctx, task->output_path);
    if (task->callback) {
        task->callback(status, task->userdata);
    }
    free(task);
    return NULL;
}

int serialize_finalize_async(SerializeContext *ctx, const char *output_path,
                             serialize_complete_fn callback, void *userdata) {
    if (!ctx || !output_path) return -1;

    struct async_serialize_task *task = malloc(sizeof(*task));
    if (!task) return -1;

    task->ctx = ctx;
    strncpy(task->output_path, output_path, sizeof(task->output_path) - 1);
    task->output_path[sizeof(task->output_path) - 1] = '\0';
    task->callback = callback;
    task->userdata = userdata;

    pthread_t tid;
    if (pthread_create(&tid, NULL, async_serialize_worker, task) != 0) {
        free(task);
        return -1;
    }
    pthread_detach(tid);
    return 0;
}
